        bytes32 state = op == 10
            ? StreamArtistAttributionCommitEncoding.claimState(_attributionClaims, m.record)
            : StreamArtistAttributionCommitEncoding.platformState(_platform, m.id);
        _commit(c, m.action, state, replay, m.primary);
