/// @notice Append-only general claims. Signatures prove account authorization, not personhood.
/// @dev GENERAL_SIGNER_CLAIM never grants Artist/op24, renderer, floor or protocol authority.
interface IStreamGeneralAttestations is IERC165 {
    enum VerificationClass {
        NONE,
        SIGNER_VERIFIED,
        OPERATOR_ASSERTED
    }
    enum AuthorityQualification {
        NONE,
        GENERAL_SIGNER_CLAIM,
        CONFIGURED_OPERATOR_CLAIM,
        NATIVE_ARTIST_HISTORY
    }

    struct Request {
        address attester;
        uint256 collectionId;
        bytes32 subjectId;
        bytes32 attestationType;
        string attesterDID;
        bytes32 schemaId;
        bytes32 canonicalizationId;
        string statementURI;
        bytes payload;
        bytes32 supersedes;
        bytes32 artistAuthorizationRecordHash;
        uint64 effectiveAt;
        uint256 nonce;
        uint64 deadline;
    }

    struct Attestation {
        address attester;
        uint256 collectionId;
        bytes32 subjectId;
        bytes32 attestationType;
        string attesterDID;
        bytes32 schemaId;
        bytes32 canonicalizationId;
        string statementURI;
        bytes32 statementHash;
        bytes32 supersedes;
        bytes32 artistAuthorizationRecordHash;
        uint64 effectiveAt;
    }

    struct Notarization {
        bytes32 artistId;
        bytes32 operativeIdentityRecordHash;
        StreamOwnerNoticeTypes.Reference legalPersonRef;
        StreamOwnerNoticeTypes.Reference instrumentRef;
        StreamOwnerNoticeTypes.Reference officiatingAuthorityIdentityRef;
        StreamOwnerNoticeTypes.Reference verifyingInstitutionIdentityRef;
    }

    struct ArtistWitness {
        uint8 subjectKind;
        uint256 nonce;
        uint256 nativeReceiptIndex;
    }

    struct Receipt {
        address recorder;
        VerificationClass verificationClass;
        AuthorityQualification authorityQualification;
        uint64 recordedAt;
        uint64 recordIndex;
        bytes32 recordChainHash;
        bytes32 authorizationDigest;
        uint256 nonce;
        uint64 deadline;
        bytes32 signatureScheme;
        bytes32 signatureBundleHash;
        bytes32 schemaDefinitionHash;
        bytes32 canonicalizationDefinitionHash;
        bytes32 profileDefinitionHash;
        bytes32 authorityFamily;
        uint8 authorizationClass;
        uint256 grantCollectionId;
        uint64 grantRevision;
        address identityRegistry;
        bytes32 identityRegistryCodeHash;
        bytes32 artistId;
        bytes32 operativeIdentityRecordHash;
        bytes32 nativeArtistEvidenceHash;
        uint8 nativeArtistAuthorityClass;
    }

    error InvalidGeneralConfiguration();
    error InvalidGeneralAttestation();
    error GeneralAuthorityRequired();
    error GeneralNonceUsed(address attester, uint256 nonce);
    error GeneralDeadlineExpired(uint64 deadline);
    error InvalidGeneralSignature(address attester);
    error GeneralParentGas(uint256 available, uint256 required);
    error GeneralDependencyChanged(address target);
    error GeneralReadFailed(address target);
    error GeneralDefinitionUnavailable(bytes32 id);
    error GeneralRecordUnknown(bytes32 hash);
    error GeneralRecordExists(bytes32 hash);
    error GeneralSupersessionMismatch(bytes32 expected, bytes32 supplied);

    event GeneralAttestationRecorded(
        uint256 indexed collectionId,
        bytes32 indexed attestationType,
        bytes32 indexed subjectId,
        bytes32 recordHash,
        address attester,
        VerificationClass verificationClass,
        AuthorityQualification authorityQualification,
        bytes32 supersedes,
        bytes32 recordChainHash,
        uint16 schemaVersion
    );
    event GeneralAttesterNonceRevoked(
        address indexed attester, uint256 indexed nonce, uint16 schemaVersion
    );

    function core() external view returns (address);
    function schemaRegistry() external view returns (address);
    function chunkStore() external view returns (address);
    function metadataAuthority() external view returns (address);
    function artistRegistry() external view returns (address);
    function verificationClass(bytes32 attestationType) external pure returns (VerificationClass);
    function operatorPolicy(bytes32 attestationType)
        external
        pure
        returns (bytes32 family, uint16 classMask);
    function deriveSubject(IStreamCollectionAttestations.Subject calldata subject)
        external
        view
        returns (bytes32);
    function attestationDigest(Request calldata request) external view returns (bytes32);
    function notarizationPayload(Notarization calldata notarization)
        external
        pure
        returns (bytes memory);
    function recordSignedAttestation(
        IStreamCollectionAttestations.Subject calldata subject,
        Request calldata request,
        bytes calldata signature
    ) external returns (bytes32);
    function recordArtistStatement(
        Request calldata request,
        ArtistWitness calldata witness,
        bytes calldata signature
    ) external returns (bytes32);
    function recordIdentityNotarization(
        IStreamCollectionAttestations.Subject calldata subject,
        Request calldata request,
        Notarization calldata notarization,
        bytes calldata signature
    ) external returns (bytes32);
    function recordOperatorAttestation(
        IStreamCollectionAttestations.Subject calldata subject,
        Request calldata request
    ) external returns (bytes32);
    function revokeAttesterNonce(uint256 nonce) external;
    function isAttesterNonceUsed(address attester, uint256 nonce) external view returns (bool);
    function attestation(bytes32 recordHash)
        external
        view
        returns (Attestation memory, Receipt memory);
    function recordArtistEvidence(bytes32 recordHash) external view returns (bytes memory);
    function recordSubject(bytes32 recordHash)
        external
        view
        returns (IStreamCollectionAttestations.Subject memory);
    /// @notice Returns the complete canonical payload; pointer is its FIRST chunk pointer.
    /// @dev Use IStreamGeneralAttestationPayloadChunks for ordered large-payload descriptors.
    function recordPayload(bytes32 recordHash)
        external
        view
        returns (address pointer, bytes memory payload);
    function recordSignatureBundle(bytes32 recordHash)
        external
        view
        returns (address pointer, bytes memory bundle);
    function latestAttestationHashFor(
        uint256 collectionId,
        bytes32 attestationType,
        bytes32 subjectId,
        address attester
    ) external view returns (bytes32);
    function recordChainHash(uint256 collectionId, bytes32 attestationType)
        external
        view
        returns (bytes32, uint64);
    function recordHashAt(uint256 collectionId, bytes32 attestationType, uint256 index)
        external
        view
        returns (bytes32);
    function payloadPointerCount(uint256 collectionId) external view returns (uint256);
    function payloadPointerAt(uint256 collectionId, uint256 index)
        external
        view
        returns (address, bytes32, bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "./IStreamSchemaRegistry.sol";

/// @notice Bounded document facts without copying registration names, URIs or chunk arrays.
/// @dev Additive to the original registry interface. Declaration hash retains provenance;
///      these facts do not reconstruct the omitted name and URI declaration preimage.
interface IStreamSchemaDocumentFacts {
    struct DocumentFacts {
        bool exists;
        IStreamSchemaRegistry.DocumentKind kind;
        IStreamSchemaRegistry.DocumentStatus status;
        bytes32 contentHash;
        bytes32 canonicalizationId;
        bytes32 supersedesId;
        uint32 totalBytes;
        uint256 chunkCount;
        bytes32 declarationHash;
    }

    /// @dev Exactly nine ABI words. Unknown IDs return zero-valued facts with exists=false.
    function documentFacts(bytes32 documentId) external view returns (DocumentFacts memory);

    /// @dev Original document ordering, including repetitions. Unknown IDs/indices revert.
    function documentChunkHashAt(bytes32 documentId, uint256 index) external view returns (bytes32);
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "../../../vendor/openzeppelin/IERC165.sol";

/// @notice Immutable interpretation documents and explicit, irreversible retirement status.
/// @dev IDs hash exact versioned names. Canonicalization references resolve an immutable
///      definition, never a mutable latest-version head. Retired definitions remain readable
///      but cannot canonicalize new document registrations. RAW_BYTES is a permanent bootstrap.
interface IStreamSchemaRegistry is IERC165 {
    enum DocumentKind {
        SCHEMA,
        CANONICALIZATION,
        CATALOG,
        DEPENDENCY
    }
    enum DocumentStatus {
        ACTIVE,
        DEPRECATED,
        ARCHIVED
    }

    struct DocumentSpec {
        string name;
        DocumentKind kind;
        bytes32 contentHash;
        bytes32 canonicalizationId;
        bytes32 supersedesId;
        string uri;
        uint32 totalBytes;
    }

    struct DocumentView {
        bool exists;
        DocumentStatus status;
        bytes32 declarationHash;
        DocumentSpec specification;
        bytes32[] chunkHashes;
    }

    error InvalidDocument();
    error DocumentAlreadyRegistered(bytes32 documentId);
    error DocumentUnknown(bytes32 documentId);
    error DocumentHashMismatch(bytes32 expected, bytes32 actual);
    error InvalidCanonicalization(bytes32 canonicalizationId);
    error InvalidDocumentPredecessor(bytes32 predecessor);
    error InvalidDocumentStatus();
    error UnauthorizedDocumentGovernance();
    error InvalidDocumentScope(uint256 scopeKey);

    event DocumentRegistered(
        uint16 schemaVersion,
        bytes32 indexed documentId,
        bytes32 indexed contentHash,
        bytes32 indexed actionId,
        bytes32 declarationHash,
        DocumentSpec specification,
        bytes32[] chunkHashes
    );
    event DocumentStatusChanged(
        uint16 schemaVersion,
        bytes32 indexed documentId,
        DocumentStatus previous,
        DocumentStatus next,
        bytes32 indexed actionId
    );

    function governanceAuthority() external view returns (address);
    function chunkStore() external view returns (address);
    function registerDocument(DocumentSpec calldata specification, bytes32[] calldata chunkHashes)
        external
        returns (bytes32 documentId);
    function setDocumentStatus(bytes32 documentId, DocumentStatus next) external;
    function document(bytes32 documentId) external view returns (DocumentView memory);
    function documentBytes(bytes32 documentId) external view returns (bytes memory);
    function documentCount() external view returns (uint256);
    function documentIdAt(uint256 index) external view returns (bytes32);
    function payloadPointerCount(uint256 scopeKey) external view returns (uint256);
    /// @dev Global scopeKey=0; accepted chunks deduplicate by (document kind, chunk hash).
    ///      Per-document chunkHashes preserve ordering and repetitions for reconstruction.
    function payloadPointerAt(uint256 scopeKey, uint256 index)
        external
        view
        returns (address pointer, bytes32 payloadFamily, bytes32 contentHash);
    function registrationTransition(
        DocumentSpec calldata specification,
        bytes32[] calldata chunkHashes
    ) external view returns (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash);
    function statusTransition(bytes32 documentId, DocumentStatus next)
        external
        view
        returns (bytes32 scopeHash, bytes32 oldValueHash, bytes32 newValueHash);
}

